#pragma once

#include <string>
#include <vector>

#include <filament/Engine.h>
#include <filament/Scene.h>
#include <filament/LightManager.h>
#include <filament/IndirectLight.h>
#include <filament/Skybox.h>
#include <filament/Texture.h>
#include <utils/Entity.h>
#include <math/vec3.h>

namespace vf_mujoco {

/// Manages scene lighting — directional (sun), point, spot, IBL + skybox.
class LightManager {
public:
    LightManager(filament::Engine* engine, filament::Scene* scene);
    ~LightManager();

    /// Setup default outdoor-style lighting (sun + fill + indirect).
    void setup_default_lighting();

    /// Load IBL from KTX cubemap files (generated by cmgen --deploy).
    /// ibl_path: path to the *_ibl.ktx file
    /// skybox_path: path to the *_skybox.ktx file
    void load_ibl(const std::string& ibl_path, const std::string& skybox_path);

    /// Add a directional light (like the sun).
    utils::Entity add_directional_light(
        float dir_x, float dir_y, float dir_z,
        float r, float g, float b,
        float intensity,
        bool cast_shadows = true);

    /// Add a point light.
    utils::Entity add_point_light(
        float pos_x, float pos_y, float pos_z,
        float r, float g, float b,
        float intensity,
        float falloff_radius = 10.0f,
        bool cast_shadows = false);

    /// Add a spot light (cone pointing in a direction).
    /// focused=true  -> Type::FOCUSED_SPOT (physically correct; cone angle is
    ///                  coupled to illumination, so narrow cones concentrate light).
    /// focused=false -> Type::SPOT (illumination decoupled from cone width, so the
    ///                  light spreads evenly across the whole cone — ideal for wide,
    ///                  soft hanging warehouse fixtures).
    utils::Entity add_spot_light(
        float pos_x, float pos_y, float pos_z,
        float dir_x, float dir_y, float dir_z,
        float r, float g, float b,
        float intensity,
        float falloff_radius,
        float inner_cone_deg,
        float outer_cone_deg,
        bool cast_shadows = false,
        bool focused = true);

    /// Remove only the directional/point/spot lights (keeps IBL + skybox).
    void clear_dynamic_lights();

    /// Set the indirect light intensity (ambient).
    void set_indirect_light_intensity(float intensity);

    /// Remove all lights.
    void clear();

private:
    filament::Engine* engine_;
    filament::Scene* scene_;
    std::vector<utils::Entity> light_entities_;
    utils::Entity sun_entity_;
    filament::IndirectLight* indirect_light_ = nullptr;
    filament::Skybox* skybox_ = nullptr;
    filament::Texture* ibl_texture_ = nullptr;
    filament::Texture* skybox_texture_ = nullptr;
};

} // namespace vf_mujoco
